function publicNav(){return `<nav class="public-nav">${logo()}<div class="public-links"><a href="#/about">${t('平台介绍','About')}</a><a href="#/workflow">${t('科研流程','Workflow')}</a><a href="#/features">${t('全部功能','Features')}</a><a href="#/guide">${t('使用指南','Guide')}</a><button class="ghost" data-action="lang">${ic('globe')} ${en?'中文':'EN'}</button><a href="#/login">${t('登录','Sign in')}</a><button class="primary" data-go="/register">${t('创建账户','Create account')} ↗</button></div></nav>`}
function footer(){return `<footer class="footer"><span>© 2026 Cy_Omics_v2.0 · ${t('从蛋白发现到生物学洞察','From protein discovery to biological insight')}</span><div class="row"><a href="#/privacy">${t('隐私政策','Privacy')}</a><a href="#/terms">${t('服务条款','Terms')}</a><a href="#/data-policy">${t('数据使用','Data use')}</a><a href="#/contact">${t('联系支持','Support')}</a></div></footer>`}
function networkSVG(large=false){let nodes=Array.from({length:24},(_,i)=>{let a=i*2.399,r=27+Math.sqrt(i)*17;return [160+Math.cos(a)*r,104+Math.sin(a)*r*.72]});return `<svg class="chart ${large?'chart-large':''}" viewBox="0 0 320 210" role="img" aria-label="Demo protein interaction network"><defs><radialGradient id="ng"><stop stop-color="#e9e0ff"/><stop offset="1" stop-color="#fff"/></radialGradient></defs><ellipse cx="160" cy="106" rx="130" ry="95" fill="url(#ng)"/>${nodes.map((n,i)=>`<path d="M160 104L${n[0]} ${n[1]} ${i>2?`L${nodes[(i+5)%24][0]} ${nodes[(i+5)%24][1]}`:''}" stroke="#b5a0ed" stroke-width=".7" opacity=".6"/>`).join('')}${nodes.map((n,i)=>`<circle class="point" data-protein="${proteins[i%8][0]}" cx="${n[0]}" cy="${n[1]}" r="${i%5===0?6:3.7}" fill="${i%5===0?'#8c63d8':'#b69ae8'}"><title>${proteins[i%8][0]} · Demo interaction</title></circle>`).join('')}<circle class="point" data-protein="AT1G56600" cx="160" cy="104" r="13" fill="#ed7dab" stroke="#fff" stroke-width="2"/><text x="180" y="100" style="fill:#7a55ba;font-size:9px">PRX12</text></svg>`}
function volcano(){let dots=Array.from({length:285},(_,i)=>{const z=Math.sin(i*57.23)*12345.67,u=z-Math.floor(z),v=(Math.sin(i*17.12)*2345.12)%1;const x=(u-.5)*7,y=Math.abs(v)*6*Math.max(.15,Math.abs(x)/3);return {x,y}});return `<svg class="chart" viewBox="0 0 320 210" role="img" aria-label="Demo volcano plot"><path class="axis" d="M36 15v162h265"/>${[0,2,4,6,8].map((n,i)=>`<path class="tick-line" d="M36 ${177-i*20}h265"/><text x="22" y="${180-i*20}">${n}</text>`).join('')}<path stroke="#a1b0c3" stroke-dasharray="3 3" d="M131 15v162M205 15v162M36 150h265"/>${dots.map((d,i)=>`<circle class="point" data-protein="${proteins[i%8][0]}" cx="${168+d.x*34}" cy="${175-d.y*25}" r="1.8" fill="${d.x>fc&&d.y>1.3?'#ef8587':d.x<-fc&&d.y>1.3?'#5b9de5':'#d4dce6'}" opacity=".8"><title>Demo · log2FC ${d.x.toFixed(2)}</title></circle>`).join('')}${[-4,-2,0,2,4].map(n=>`<text x="${164+n*29}" y="191">${n}</text>`).join('')}<text x="135" y="207">log₂ (Fold Change)</text><text transform="translate(11 140) rotate(-90)">−log₁₀ (P value)</text></svg>`}
const goTerms=['Response to oxidative stress','Oxidation-reduction process','Response to water deprivation','Antioxidant activity','Cellular response to stress','Hydrogen peroxide catabolism','Cell wall organization','Response to abscisic acid'];
function enrichment(){return `<svg class="chart" viewBox="0 0 320 210" role="img" aria-label="Demo GO enrichment"><path class="axis" d="M143 12v166h164"/>${goTerms.map((n,i)=>`<text x="136" y="${27+i*19}" text-anchor="end" style="font-size:7.4px">${n}</text><rect data-term="${i}" x="145" y="${18+i*19}" width="${137-i*13}" height="10" rx="1" fill="${i<3?'#a27add':'#c7abea'}" style="cursor:pointer"><title>${n} · Demo Data · click to view proteins</title></rect>`).join('')}${[0,2,4,6,8,10].map((n,i)=>`<text x="${142+i*30}" y="191">${n}</text>`).join('')}<text x="191" y="207">−log₁₀ (FDR)</text></svg>`}
function structure(){let d='';for(let i=0;i<230;i++){let a=i*.19,x=150+Math.cos(a)*42+Math.sin(i*.035)*48,y=92+Math.sin(a)*23+Math.cos(i*.032)*37;d+=`${i?'L':'M'}${x.toFixed(2)} ${y.toFixed(2)} `}return `<svg class="chart" viewBox="0 0 300 185" role="img" aria-label="Illustrative protein ribbon, not an actual structure"><defs><linearGradient id="ribbon"><stop stop-color="#67b8e7"/><stop offset=".45" stop-color="#367ce0"/><stop offset=".75" stop-color="#605dd5"/><stop offset="1" stop-color="#eeb563"/></linearGradient></defs><path d="${d}" stroke="url(#ribbon)" fill="none" stroke-width="3.6" stroke-linecap="round"/><text x="150" y="177" text-anchor="middle">Illustrative ribbon · not a molecular model</text></svg>`}
function publicStages(){return `<div class="five-public">${stages.map((s,i)=>`<article class="public-stage" style="--c:var(--${s[2]})" data-go="/demo/stage/${i}"><small>STAGE 0${i+1}</small><h3>${t(s[0],['Discovery & quantification','Functional interpretation','Network & mechanisms','Structure & localization','Integrated evidence'][i])}</h3><p>${s[1]}</p><small>${s[4]}</small><span class="arrow">${t('探索演示','Explore demo')} →</span></article>`).join('')}</div>`}
function portal(){return `<div class="portal">${publicNav()}<section class="hero"><div><div class="eyebrow">INTEGRATED PROTEOMICS ANALYSIS PLATFORM</div><h1>${t('让每一份蛋白证据，<br>通向<em>生物学发现。</em>','Connect protein evidence.<br>Unlock <em>biological insight.</em>')}</h1><p>${t('从定量差异到功能、互作与结构，将分散的分析结果串联为一条完整的科研证据链。为研究者打造统一的蛋白质组学工作空间。','Connect quantification, function, interactions and structure in one coherent research workspace. Follow every protein from discovery to biological interpretation.')}</p><div class="row"><button class="primary" data-go="/register">${t('开启科研工作空间','Start your workspace')} →</button><button data-go="/demo/analysis">${ic('flask')} ${t('探索演示项目','Explore demo project')}</button><button class="ghost" data-go="/workspace/projects">${t('我的私人项目','My private projects')} →</button></div><div class="row note">${ic('lock')} ${t('项目默认私有 · 统一蛋白身份 · 全程证据可追溯','Private projects · Unified protein identity · Traceable evidence')}</div></div><div class="hero-art">${networkSVG()}<div class="art-label a"><small>PROTEIN KNOWLEDGE HUB</small><strong>${t('一份身份，多维证据','One identity. Connected evidence.')}</strong></div><div class="art-label b"><span class="badge success">5 CONNECTED STAGES</span><strong>Discovery → Insight</strong></div></div></section><div class="portal-band"><span>QUANTIFICATION</span><span>FUNCTION</span><span>NETWORK</span><span>STRUCTURE</span><span>BIOLOGICAL INSIGHT</span></div><section class="portal-section"><div class="section-head between"><div><div class="eyebrow">A CONNECTED RESEARCH JOURNEY</div><h2>${t('五个阶段，一条完整的科研故事线','Five stages. One connected research journey.')}</h2><p class="muted">${t('每一个结论，都可以回到蛋白质本身寻找证据。','Trace every conclusion back to its protein evidence.')}</p></div><a href="#/workflow" class="link">${t('了解工作流程','View workflow')} ↗</a></div>${publicStages()}</section><section class="portal-section grid-2" style="padding-top:0"><article class="panel panel-pad"><div class="eyebrow">PROTEIN KNOWLEDGE HUB</div><h2>${t('同一蛋白，连接所有分析','Every analysis, connected to one protein')}</h2><p class="muted" style="margin:14px 0">${t('基于物种、Accession、Isoform 与序列 SHA256 建立可追溯身份，让表达、通路、结构和互作不再割裂。','Trace sequence identity, expression, pathways, domains and interactions in a unified evidence hub.')}</p><button data-go="/hub-intro">${t('探索蛋白知识中心','Explore the Knowledge Hub')} →</button></article><article class="panel panel-pad"><div class="eyebrow" style="color:var(--teal)">KEY PROTEIN DISCOVERY</div><h2>${t('从差异蛋白，到关键候选','From differential proteins to key candidates')}</h2><p class="muted" style="margin:14px 0">${t('并列比较多维证据与缺失项。明确区分预测、计算关联和实验依据，形成可验证的机制假设。','Compare evidence and missing dimensions. Distinguish predictions from experimental evidence to form testable hypotheses.')}</p><button data-go="/discovery-intro">${t('了解关键蛋白发现','Discover key proteins')} →</button></article></section>${footer()}</div>`}
function side(){const nav=[['home','科研工作空间','Dashboard','dashboard'],['folder','我的项目','My projects','projects'],['database','数据管理','Data management','data']];return `<aside class="sidebar">${logo()}<div class="side-body"><div class="nav-label">${t('研究工作空间','RESEARCH WORKSPACE')}</div>${nav.map(n=>navItem(n)).join('')}<a class="nav-item ${/analysis|stage|tool/.test(route)?'active':''}" href="#/demo/analysis">${ic('flask')}${t('项目分析','Project analysis')}<span style="margin-left:auto">⌄</span></a>${stages.map((s,i)=>`<a class="nav-item sub ${route==='/demo/stage/'+i?'active':''}" href="#/demo/stage/${i}">${t(s[0],['Discovery','Function','Network','Structure','Evidence'][i])}</a>`).join('')}${[['qc','样本质量控制'],['preprocessing','数据预处理'],['gsea','GSEA 富集'],['pfam','Pfam 结构域']].map(([id,label])=>`<a class="nav-item sub ${route==='/demo/tool/'+id?'active':''}" href="#/demo/tool/${id}">${en?(scienceTools.find(x=>x[0]===id)[2]):label}</a>`).join('')}<div class="nav-label" style="margin-top:22px">${t('证据与发现','EVIDENCE & DISCOVERY')}</div>${[['layers','蛋白质知识中心','Protein Knowledge Hub','hub'],['star','关键蛋白发现','Key Protein Discovery','discovery'],['report','综合科研报告','Research reports','reports'],['task','我的分析任务','Analysis tasks','tasks']].map(n=>navItem(n)).join('')}<div class="nav-label" style="margin-top:22px">${t('管理与支持','MANAGEMENT')}</div>${[['user','项目协作','Collaboration','collaboration'],['settings','用户账户','Account settings','account'],['settings','管理员后台','Administration','admin'],['help','帮助与文档','Help & documentation','help']].map(n=>navItem(n)).join('')}</div><div class="sidebar-foot"><div class="row"><span class="dot" style="color:#7ab4ee"></span>${t('演示模式 · 仅本设备保存','Demo mode · device-local')}</div><a href="#/">← ${t('返回公开门户','Back to public portal')}</a></div></aside>`}
function navItem(n){return `<a class="nav-item ${route==='/demo/'+n[3]?'active':''}" href="#/demo/${n[3]}">${ic(n[0])}${t(n[1],n[2])}</a>`}
function shell(body){return `${side()}<div class="shell"><header class="topbar"><div class="row"><button class="ghost hamburger" data-action="menu">☰</button><strong>${t('综合蛋白质组学分析平台','Integrated Proteomics Platform')}</strong><span class="muted">Integrated Proteomics Analysis Platform</span></div><div class="row"><button class="ghost" data-action="lang">${en?'中文':'EN'}</button><a href="#/demo/help">${ic('help')}</a><button class="ghost" data-action="notifications" aria-label="Notifications">${ic('bell')}</button><span class="avatar">D</span><span class="note">${t('演示访客','Demo visitor')}</span></div></header><main class="content"><div class="breadcrumb">${t('科研工作空间','Workspace')}<span>/</span>${t('演示项目','Demo project')}<span>/</span>${esc(project?.name||'Demo')}</div><div class="banner"><span>${badge()}　${t('当前为独立演示空间，所有图表和注释仅供交互体验，请勿上传真实研究数据。','Isolated demo workspace. All charts and annotations are illustrative. Do not upload real research data.')}</span><a href="#/login">${t('登录私人空间','Sign in')} →</a></div>${body}</main></div>`}
function projectHeader(active=0){return `<section class="panel project-header"><div class="between"><div class="row"><div class="project-icon">${ic('leaf')}</div><div><div class="row"><h2 class="project-name">${esc(project?.name||'Demo project')}</h2>${badge()}</div><p class="note" style="margin-top:6px">${esc(project?.desc||'演示研究项目')}</p><div class="project-meta"><span>${ic('database')} ${esc(project?.species||'Arabidopsis thaliana')}</span><span>${t('样本','Samples')}: ${project?.samples||0} （Control 3 / Stress 3）</span><span>${t('项目类型','Type')}: ${t('定量蛋白质组','Quantitative proteomics')}</span></div></div></div><div class="row"><button data-go="/demo/collaboration">${ic('settings')} ${t('项目设置','Settings')}</button><button class="primary" data-go="/demo/reports">${ic('download')} ${t('导出报告','Export report')}</button></div></div><div class="stages">${stages.map((s,i)=>`<a class="stage ${active===i?'active':''}" style="--c:var(--${s[2]})" href="#/demo/stage/${i}"><span class="stage-num">0${i+1}</span><div><strong>${t(s[0],['Discovery','Function','Network','Structure','Evidence'][i])}</strong><small>${s[4]}</small></div><span class="check">↗</span></a>`).join('')}</div></section>`}
function stats(){return `<div class="stats">${[['database','总蛋白数','Total proteins','5,842','#2175e5','Identified proteins'],['arrow','上调蛋白','Up-regulated','312','#e6787e','log₂FC > 1'],['arrow','下调蛋白','Down-regulated','287','#4599d4','log₂FC < −1'],['network','差异蛋白 DEPs','Differential proteins','599','#8a62d5','FDR < 0.05']].map(s=>`<div class="panel stat"><span class="stat-icon" style="color:${s[4]};background:${s[4]}10">${ic(s[0])}</span><div><small>${t(s[1],s[2])}</small><b style="color:${s[4]}">${s[3]}</b></div><span class="stat-note">${s[5]}</span></div>`).join('')}</div>`}
function charts(){return `<div class="charts"><article class="panel chart-card"><div class="between chart-title"><h3>${t('火山图','Volcano plot')}</h3><span class="badge">Stress vs Control</span></div>${volcano()}<div class="chart-footer"><div class="legend"><span><i style="background:#ef8587"></i>Up 312</span><span><i style="background:#5b9de5"></i>Down 287</span><span><i style="background:#cdd6e0"></i>NS</span></div><a href="#/demo/tool/differential">↗</a></div></article><article class="panel chart-card"><div class="between chart-title"><h3>${t('GO 富集分析','GO enrichment')}</h3><small>Biological Process · Top 8</small></div>${enrichment()}<div class="chart-footer"><span>${t('点击通路查看关联蛋白','Click a term to view linked proteins')}</span><a href="#/demo/tool/go">↗</a></div></article><article class="panel chart-card"><div class="between chart-title"><h3>${t('PPI 蛋白互作网络','Protein interaction network')}</h3><small>STRING · Demo</small></div>${networkSVG()}<div class="chart-footer"><div class="legend"><span><i style="background:#ed7dab"></i>${t('候选关键蛋白','Key candidate')}</span><span><i style="background:#aa87df"></i>${t('关联蛋白','Interactors')}</span></div><a href="#/demo/tool/ppi">↗</a></div></article></div>`}
function proteinList(){const list=proteins.filter(p=>p.join(' ').toLowerCase().includes(search.toLowerCase())&&Math.abs(p[3])>=fc&&Number(p[4])<=pval);return `<div class="panel table-panel"><div class="panel-title between"><h3>${t('差异蛋白列表','Differential proteins')}</h3><small>${list.length} / 599</small></div><div class="search"><input aria-label="Search proteins" id="protein-search" placeholder="${t('搜索蛋白 ID / 名称…','Search protein ID / name…')}" value="${esc(search)}"></div><table><thead><tr><th>Protein ID</th><th>log₂FC</th><th>P value</th><th>↕</th></tr></thead><tbody>${list.map(p=>`<tr class="${selected[0]===p[0]?'selected':''}" data-protein="${p[0]}" tabindex="0"><td>${p[0]}</td><td>${p[3]}</td><td>${p[4]}</td><td class="${p[3]>0?'up':'down'}">${p[3]>0?'↑':'↓'}</td></tr>`).join('')||`<tr><td colspan="4">${t('无匹配演示蛋白','No matching demo proteins')}</td></tr>`}</tbody></table><div class="table-foot">${t('演示数据集展示 8 条关联记录','8 linked records in the demo dataset')}<br><br>${t('点击 Protein ID 查看统一证据','Select a Protein ID to inspect evidence')} →</div></div>`}
const proteinTabs=[['overview','概览','Overview'],['gsea','GSEA 通路','GSEA'],['pfam','Pfam 证据','Pfam'],['annotation','功能注释','Function'],['sequence','序列 / BLAST','Sequence / BLAST'],['domains','结构域','Domains'],['structure','三维结构','Structure'],['location','亚细胞定位','Localization'],['interaction','互作网络','Network'],['evidence','证据溯源','Provenance']];
function proteinDetail(){const p=selected;return `<article class="panel"><div class="protein-head"><div><div class="row"><h2>${p[0]}</h2><span class="badge ${p[3]>0?'success':''}">${p[3]>0?'↑ Up':'↓ Down'} · log₂FC ${p[3]}</span>${badge()}</div><p>${p[2]} · ${p[1]}　|　${p[5]} aa　|　Arabidopsis thaliana</p></div><button data-action="candidate">${ic('star')} ${saved.has(p[0])?t('已加入候选集','In candidates'):t('加入候选集','Add candidate')}</button></div><div class="tabs protein-tabs">${proteinTabs.map(x=>`<button class="${proteinTab===x[0]?'active':''}" data-ptab="${x[0]}">${t(x[1],x[2])}</button>`).join('')}</div>${proteinBody()}</article>`}
function proteinBody(){const p=selected;if(['gsea','pfam'].includes(proteinTab))return `<div class="protein-evidence"><h3>${proteinTab==='gsea'?'GSEA':'Pfam'} · ${p[0]}</h3><p class="note" style="margin:15px 0">${t('NOT IMPLEMENTED · 当前演示蛋白没有真实分析证据，不生成虚构结果。','NOT IMPLEMENTED · No real evidence is available for this demo protein.')}</p><button data-go="/demo/tool/${proteinTab}">${t('打开分析模块','Open module')} →</button></div>`;if(proteinTab==='overview')return `<div class="evidence-grid"><section class="mini"><h3>${t('关键摘要','Evidence summary')}</h3><dl class="facts"><dt>${t('表达变化','Expression')}</dt><dd class="${p[3]>0?'up':'down'}">${p[3]>0?'↑ Up-regulated':'↓ Down-regulated'} (${p[3]})</dd><dt>${t('主要功能','Function')}</dt><dd>${p[2]}</dd><dt>${t('关联通路','Pathway')}</dt><dd><a class="link" data-term="0">Oxidative stress ↗</a></dd><dt>${t('亚细胞定位','Localization')}</dt><dd>${p[6]} <small>· ${t('预测演示','Prediction demo')}</small></dd><dt>${t('结构域','Domain')}</dt><dd>${p[7]}</dd><dt>${t('互作蛋白','Interactors')}</dt><dd><a href="#/demo/tool/ppi" class="link">15 ${t('个关联蛋白','interactors')} ↗</a></dd></dl></section><section class="mini"><div class="between"><h3>${t('三维结构示意','Structure illustration')}</h3><small>Demo</small></div>${structure()}<div class="note">${t('示意图，不代表真实 AlphaFold 模型','Illustration, not an AlphaFold model')}</div></section><section class="mini"><h3>${t('结构域分布','Domain architecture')}</h3>${domain()}<div class="legend"><span><i style="background:#9d77df"></i>${p[7]}</span></div><p class="note" style="margin-top:10px">SMART / CDD · Demo annotation</p><a class="link note" href="#/demo/tool/smart">${t('查看结构域证据','View domain evidence')} →</a></section></div>`;
if(proteinTab==='sequence')return `<div class="protein-evidence stack"><div class="between"><h3>${t('序列身份与同源证据','Sequence identity & homology')}</h3>${pending()}</div><dl class="facts"><dt>Taxonomy ID</dt><dd>3702</dd><dt>Source</dt><dd>TAIR · ${p[0]} · Isoform 1 · Demo metadata</dd><dt>SHA256</dt><dd>${t('无真实序列，未计算；上传后由后端规范化并计算','No real sequence; computed by backend after import')}</dd></dl><div class="sequence">${t('此演示不含真实 FASTA 序列。请在正式服务接入后导入序列，平台将按序列 SHA256 去重，并保持项目内统一身份。','This demo contains no real FASTA sequence. Import through the configured backend to compute SHA256 and link sequence identity.')}</div><button data-go="/demo/tool/blast">Local BLAST →</button></div>`;
if(proteinTab==='domains')return `<div class="protein-evidence"><h3>${p[7]}</h3>${domain()}<p class="note">Demo Data · ${t('示意结构域位置，不作为实际序列注释。','Illustrative domain positions, not sequence annotation.')}</p><div class="row" style="margin-top:18px"><button data-go="/demo/tool/smart">SMART →</button><button data-go="/demo/tool/cdd">CDD →</button></div></div>`;
if(proteinTab==='structure')return `<div class="protein-evidence grid-2"><div>${structure()}<p class="note">${t('仅为丝带示意，不包含原子坐标或 pLDDT。','Ribbon illustration only; no coordinates or pLDDT.')}</p></div><div class="stack"><div class="mini"><h3>AlphaFold · ${t('预测结构','Predicted structure')}</h3>${pending()}<button class="link" data-go="/demo/tool/alphafold"> ${t('查看模块','Open module')} →</button></div><div class="mini"><h3>PDB · ${t('实验结构','Experimental structure')}</h3>${pending()}<p class="note">${t('未检索，不声称存在实验结构','Not queried; no experimental structure claimed')}</p><button class="link" data-go="/demo/tool/pdb">${t('检索结构','Search structures')} →</button></div></div></div>`;
if(proteinTab==='location')return `<div class="protein-evidence"><h3>${p[6]} · ${t('预测示例','Illustrative prediction')}</h3><p class="note" style="margin:15px 0">Demo Data · ${t('定位与网络关联仅用于体验，不代表实验定位证据。','Illustrative localization and network associations; no experimental evidence.')}</p><button data-go="/demo/tool/localization">${t('查看亚细胞定位模块','Open localization module')} →</button></div>`;
if(proteinTab==='interaction')return `<div class="protein-evidence grid-2">${networkSVG()}<div><h3>${t('关联蛋白','Linked proteins')}</h3>${proteins.filter(x=>x!==p).slice(0,4).map(x=>`<div class="list-row"><a class="link" data-protein="${x[0]}">${x[0]} ↗</a><small>${x[1]}</small></div>`).join('')}</div></div>`;
if(proteinTab==='annotation')return `<div class="protein-evidence"><div class="between"><h3>${p[2]} · ${t('功能证据','Functional evidence')}</h3>${badge()}</div><table style="margin-top:15px"><thead><tr><th>Source</th><th>Annotation</th><th>Linked evidence</th></tr></thead><tbody><tr data-term="0"><td>GO</td><td>Response to oxidative stress</td><td>View proteins ↗</td></tr><tr data-term="1"><td>KEGG</td><td>Metabolic pathways</td><td>View proteins ↗</td></tr><tr><td>eggNOG</td><td>Demo functional class</td><td>Illustrative only</td></tr></tbody></table></div>`;
return `<div class="protein-evidence"><h3>${t('可追溯证据记录','Traceable evidence records')}</h3><table style="margin-top:15px"><thead><tr><th>Source</th><th>Version</th><th>Parameters</th><th>Time / task</th><th>Type</th></tr></thead><tbody>${['Differential expression','GO / KEGG','STRING','SMART / CDD','AlphaFold / PDB'].map(x=>`<tr><td>${x}</td><td>Demo fixture v1</td><td>Illustrative only</td><td>Not executed</td><td>Demo Data</td></tr>`).join('')}</tbody></table><p class="note" style="margin-top:15px">${t('正式结果将记录输入、任务 ID、软件与数据库版本、参数及时间；当前未执行真实分析。','Production evidence will include input, task ID, software/database versions, parameters and timestamps. No real analysis has run.')}</p></div>`}
function domain(){return `<div class="domain"><div class="domain-line"><div class="domain-bar signal"></div><div class="domain-bar"></div></div><div class="domain-ticks"><span>1</span><span>80</span><span>160</span><span>240</span><span>${selected[5]} aa</span></div></div>`}
function analysis(){return projectHeader(0)+`<div class="between"><div class="row"><h2>${t('差异分析结果','Differential analysis results')}</h2><small class="muted">Stress vs Control</small></div><button class="ghost" data-go="/demo/tool/differential">${t('分析参数','Analysis parameters')} ⚙</button></div>${stats()}${charts()}<div class="lower">${proteinList()}${proteinDetail()}</div>`}
function stagePage(i){const s=stages[i];let body=i===0?`<div class="grid-2"><div class="panel panel-pad"><h3>${t('数据发现与质量控制','Data discovery & quality control')}</h3><p class="note" style="margin:12px 0">${t('导入 → 缺失值处理 → 标准化 → 差异筛选 → 样本质量检查','Import → missing values → normalization → differential screening → quality control')}</p><button class="primary" data-go="/demo/tool/import">${t('导入数据','Import data')}</button> <button data-go="/demo/analysis">${t('查看演示结果','View demo results')} →</button></div><div class="panel panel-pad"><h3>${t('分析输出','Analysis output')}</h3><p class="note" style="margin:12px 0">DEPs · Volcano · Heatmap · PCA · Correlation</p><button data-go="/demo/tool/differential">${t('差异筛选与可视化','Differential screening')} →</button></div></div>`:i===2?`<div class="grid-2"><div class="panel panel-pad">${networkSVG(true)}</div><div class="panel panel-pad"><h3>${t('功能模块与关键节点','Modules & key nodes')}</h3>${proteins.slice(0,4).map((p,j)=>`<div class="list-row"><a class="link" data-protein="${p[0]}">${p[0]} · ${p[1]}</a><span class="badge">Module ${j%2+1}</span></div>`).join('')}<p class="note" style="margin-top:20px">Demo Data · ${t('连接数和模块为教学示例，未查询 STRING。','Illustrative modules; STRING has not been queried.')}</p></div></div>`:i===4?discoveryContent():`<div class="tool-grid">${tools.filter(x=>x[3]===i).map(toolCard).join('')}</div>`;if(i===0)body+=`<div class="tool-grid" style="margin-top:18px">${scienceTools.filter(x=>x[3]===0).map(toolCard).join('')}</div>`;return projectHeader(i)+`<div class="page-title"><div class="eyebrow" style="color:var(--${s[2]})">STAGE 0${i+1}</div><h1>${s[1]}</h1><p>${s[4]}</p></div>${body}<div class="between" style="margin-top:24px"><button data-go="/demo/stage/${Math.max(0,i-1)}">← ${t('上一阶段','Previous stage')}</button><button data-go="/demo/stage/${Math.min(4,i+1)}">${t('下一阶段','Next stage')} →</button></div>`}
function toolCard(x){return `<article class="panel tool-card" data-go="/demo/tool/${x[0]}"><span style="color:var(--${stages[x[3]][2]})">${ic(stages[x[3]][3])}</span><h3>${t(x[1],x[2])}</h3><p>${x[4]}</p><div class="between">${pending()}<span class="link">${t('打开模块','Open module')} →</span></div></article>`}
function title(a,b,action=''){return `<div class="page-title between"><div><h1>${a}</h1><p>${b}</p></div>${action}</div>`}
function toolPage(id){if(id==='import')return title(t('数据导入与定量','Data import & quantification'),t('统一输入 · 本地只读预览 · 不上传、不执行科研计算','Unified inputs · local read-only preview · no upload or compute'))+uploadPanel();if(scienceTools.some(x=>x[0]===id))return projectHeader(scienceTools.find(x=>x[0]===id)[3])+sciencePage(id,en);const x=tools.find(x=>x[0]===id);if(!x)return emptyPage();return projectHeader(x[3])+title(t(x[1],x[2]),t('同一项目 · 同一蛋白身份 · 关联全部分析证据','One project · One protein identity · Connected evidence'),pending())+`<div class="panel panel-pad stack"><div class="between"><h3>${t('分析输入与参数','Input & parameters')}</h3><a class="link" href="#/demo/hub">Protein Knowledge Hub ↗</a></div>${id==='import'?uploadPanel():`<div class="form-grid"><label class="field">${t('输入蛋白','Protein input')}<select id="tool-protein">${proteins.map(p=>`<option ${p===selected?'selected':''} value="${p[0]}">${p[0]} · ${p[1]}</option>`).join('')}</select></label><label class="field">${t('输入范围','Scope')}<select><option>${t('当前蛋白','Current protein')}</option><option>${t('差异蛋白集 DEPs','Differential protein set')}</option><option>${t('候选蛋白集','Candidate protein set')}</option></select></label>${id==='differential'?`<label class="field">|log₂ Fold Change| ≥<input type="number" step="0.1" min="0" max="5" id="fc" value="${fc}"></label><label class="field">P value ≤<input type="number" step="0.01" min="0" max="1" id="pvalue" value="${pval}"></label>`:`<label class="field">${t('证据来源','Evidence source')}<input value="${esc(x[2])}" readonly></label><label class="field">${t('执行模式','Execution mode')}<input value="${t('独立 Linux Worker · 尚未连接','Independent Linux Worker · not connected')}" readonly></label>`}</div>`}<div class="between"><p class="note">${t('参数仅保留在原型中；真实分析需要配置独立 FastAPI 服务。','Parameters are for preview only. Real analysis requires an independent FastAPI service.')}</p><div class="row">${id==='differential'?`<button data-action="filter">${t('应用演示筛选','Apply demo filter')}</button>`:''}<button class="primary" data-action="run">${t('提交分析任务','Submit analysis')}</button></div></div></div><div style="margin-top:18px" class="stack">${toolResults(id)}</div>`}
function uploadPanel(){return '<div id="unified-import"></div>'}
let localPreviewRead = 0, localPreviewReader = null;
let disposeAssociationUI = null;
const authStatusRoutes=createAuthStatusRoutes();
let disposeAuthStatusView=null;
const signupRoutes=createSignupRoutes({transport:createSignupTransport({enabled:true})});
let disposeSignupView=null;
const loginRoutes=createLoginRoutes({transport:createLoginTransport({enabled:true})});
let disposeLoginView=null;
const privateProjectRoutes=createPrivateProjectRoutes({transport:createPrivateProjectTransport({enabled:true,sampleDesignsEnabled:true,rawQcEnabled:true,rawQcArtifactsEnabled:true})});
let disposePrivateProjectView=null;
function cancelLocalPreview(){
  localPreviewRead++;
  const reader=localPreviewReader;
  localPreviewReader=null;
  if(reader)reader.cancel().catch(()=>{});
}
function fastaPreview(result){
  return `<section class="mini" aria-label="Real FASTA local preview"><h3>${t('真实FASTA本地预览，未上传、未分析','Real FASTA local preview — not uploaded or analyzed')}</h3><p class="note">${t('仅结构检查，未验证氨基酸字母表。不关联演示图表；刷新、离页或重绘即清除。','Structure checks only; the amino acid alphabet is not validated. No demo-chart linkage. Refresh, navigation or redraw clears the preview.')}</p><dl class="facts" style="margin-top:18px"><dt>${t('记录总数','Total records')}</dt><dd data-fasta-count="records">${result.recordCount}</dd><dt>${t('总残基长度（结构字符计数）','Total length (structural character count)')}</dt><dd data-fasta-count="length">${result.totalSequenceLength}</dd></dl><p class="note">${t('长度为非空白 UTF-16 代码单元计数，不验证生物学有效性；未保存数据集、未去重。','Lengths count non-whitespace UTF-16 code units, without biological validation, dataset persistence or sequence deduplication.')}</p><div style="overflow:auto;max-height:380px"><table aria-label="FASTA ID and length preview"><thead><tr><th>ID</th><th>${t('长度','Length')}</th></tr></thead><tbody>${result.preview.map(item=>`<tr><td>${esc(item.id)}</td><td>${item.length}</td></tr>`).join('')}</tbody></table></div><p class="note">${t('仅显示前','Showing only the first ')} ${result.preview.length} ${t('条 ID 与长度，不显示序列。',' IDs and lengths; sequences are not displayed.')}</p></section>`;
}
function proteinGroupsQuantification(result,type){
  const kind=type==='lfq'?'LFQ intensity':'Intensity';
  const columns=type==='lfq'?result.lfqColumns:result.intensityColumns;
  const heading=`<p><strong data-quant-type>${esc(kind)}</strong> · <span data-quant-count>${columns.length}</span> ${t('个原始样本列','original sample columns')}</p>`;
  if(!columns.length)return heading+`<p role="status">${esc(t(`未找到 ${kind} 样本列；未使用其他类型替代。`,`No ${kind} sample columns found; no other type substituted.`))}</p>`;
  const idIndex=result.headers.indexOf('Protein IDs');
  return heading+`<details class="faq"><summary>${t('查看当前类型原始样本列与样本名','View selected original sample columns and names')} (${columns.length})</summary><div style="overflow:auto;max-height:320px"><table aria-label="Original sample columns"><thead><tr><th>${t('类型','Type')}</th><th>${t('原始列名','Original column')}</th><th>${t('原始样本名','Original sample name')}</th></tr></thead><tbody>${columns.map(x=>`<tr><td>${esc(kind)}</td><td>${esc(x.columnName)}</td><td>${esc(x.sampleName)}</td></tr>`).join('')}</tbody></table></div></details><p class="note">${t('前 10 条原始记录的当前类型量化值；仅预览，未转换、未归一化、未分析。','Selected quantification values from the first 10 original records; preview only, without conversion, normalization or analysis.')}</p><div style="overflow:auto;max-height:380px"><table aria-label="Selected quantification preview"><thead><tr><th>Protein IDs</th>${columns.map(x=>`<th>${esc(x.columnName)}</th>`).join('')}</tr></thead><tbody>${result.previewRows.map(row=>`<tr><td style="white-space:pre">${esc(row[idIndex])}</td>${columns.map(x=>`<td style="white-space:pre">${esc(row[x.index])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}
function mountProteinGroupsPreview(preview,result){
  preview.innerHTML=proteinGroupsPreview(result);
  const select=preview.querySelector('[data-quant-select]');
  select.addEventListener('change',()=>{
    if(preview.isConnected)preview.querySelector('[data-quant-preview]').innerHTML=proteinGroupsQuantification(result,select.value);
  });
}
function proteinGroupsPreview(result){
  return `<section class="mini" aria-label="Real file local preview"><h3>${t('真实文件本地预览，未上传、未分析','Real file local preview — not uploaded or analyzed')}</h3><dl class="facts" style="margin-top:18px"><dt>${t('数据行数','Data rows')}</dt><dd data-preview-count="rows">${result.rowCount}</dd><dt>${t('列数','Columns')}</dt><dd data-preview-count="columns">${result.columnCount}</dd><dt>Intensity</dt><dd data-preview-count="intensity">${result.intensityColumns.length}</dd><dt>LFQ intensity</dt><dd data-preview-count="lfq">${result.lfqColumns.length}</dd></dl><p class="note">${t('原始值、0、空值及多 ID 字段保持不变。未推断分组；不关联演示图表；刷新或离开此页即清除预览。','Original values, zeros, empty cells and multi-ID fields are preserved. No grouping or demo-chart linkage. Refresh or leave this page to clear the preview.')}</p><label class="field">${t('当前量化类型','Current quantification type')}<select data-quant-select aria-label="Quantification type"><option value="intensity">Intensity</option><option value="lfq">LFQ intensity</option></select></label><div data-quant-preview>${proteinGroupsQuantification(result,'intensity')}</div><details class="faq"><summary>${t('查看前','View first ')} ${result.previewRows.length} ${t('条原始记录（仅预览，不代表筛选）',' original records (preview only, not filtering)')}</summary><div style="overflow:auto;max-height:380px"><table aria-label="proteinGroups local table preview"><thead><tr>${result.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${result.previewRows.map(row=>`<tr>${row.map(value=>`<td style="white-space:pre">${esc(value)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details></section>`;
}
function toolResults(id){if(id==='differential')return `<div class="panel panel-pad"><div class="tabs">${['volcano','heatmap','pca','correlation'].map((x,i)=>`<button data-chart="${x}" class="${chartTab===x||chartTab==='overview'&&i===0?'active':''}">${['Volcano','Heatmap','PCA','Correlation'][i]}</button>`).join('')}</div>${chartTab==='heatmap'?heatmap():chartTab==='correlation'?heatmap(true):chartTab==='pca'?pca():volcano()}<p class="note">Demo Data · ${t('筛选仅影响演示图和蛋白列表，未执行统计检验','Filters affect demo visualizations only; no statistical test has run')}</p></div><div class="lower">${proteinList()}${proteinDetail()}</div>`;if(id==='go'||id==='kegg')return `<div class="grid-2"><div class="panel panel-pad">${enrichment()}</div><div class="panel panel-pad"><h3>${t('通路关联差异蛋白','Pathway-linked differential proteins')}</h3>${goTerms.slice(0,5).map((x,i)=>`<div class="list-row" data-term="${i}" style="cursor:pointer"><span>${id==='kegg'?['Metabolic pathways','Glutathione metabolism','Plant hormone signaling','Carbon metabolism','Biosynthesis of metabolites'][i]:x}</span><span class="link">↗</span></div>`).join('')}</div></div>`;if(id==='ppi')return `<div class="panel">${networkSVG(true)}</div>`;if(['smart','cdd','alphafold','pdb','localization','blast','eggnog'].includes(id))return proteinDetail();return `<div class="panel empty"><h3>${t('真实分析服务尚未接入','Analysis service not connected')}</h3><p>${t('文件校验成功不会触发后台计算。连接服务后，任务、结果与序列将统一归属当前项目。','Local validation does not execute analysis. The backend will bind tasks, results and sequences to this project.')}</p></div>`}
function heatmap(corr=false){const n=corr?6:8,m=6;return `<svg class="chart chart-large" viewBox="0 0 500 310" role="img" aria-label="Demo heatmap">${Array.from({length:n},(_,i)=>Array.from({length:m},(_,j)=>{let v=corr?1-Math.abs(i-j)*.12:Math.sin(i*9+j*4);return `<rect x="${120+j*45}" y="${25+i*29}" width="43" height="27" fill="${v>0?`rgba(222,108,131,${Math.abs(v)*.7+.15})`:`rgba(68,142,208,${Math.abs(v)*.7+.15})`}"/><text x="${141+j*45}" y="${42+i*29}" text-anchor="middle" style="fill:white">${corr?v.toFixed(2):''}</text>`}).join('')+`<text x="110" y="${42+i*29}" text-anchor="end">${corr?['Ctrl 1','Ctrl 2','Ctrl 3','Stress 1','Stress 2','Stress 3'][i]:proteins[i][0]}</text>`).join('')}${['Ctrl 1','Ctrl 2','Ctrl 3','Stress 1','Stress 2','Stress 3'].map((x,j)=>`<text x="${141+j*45}" y="${45+n*29}" text-anchor="middle">${x}</text>`).join('')}<text x="250" y="300" text-anchor="middle">Demo Data · ${corr?'Illustrative sample correlations':'Illustrative normalized abundance'}</text></svg>`}
function pca(){return `<svg class="chart chart-large" viewBox="0 0 500 310" role="img" aria-label="Demo PCA"><path class="axis" d="M60 20v240h390"/><ellipse cx="170" cy="120" rx="65" ry="50" fill="#e9f2ff"/><ellipse cx="350" cy="185" rx="60" ry="45" fill="#faeaf0"/>${[[140,105],[180,90],[190,145],[320,180],[355,165],[370,210]].map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="6" fill="${i<3?'#6d9fde':'#dc8da4'}"/><text x="${p[0]+10}" y="${p[1]}">${i<3?'Control':'Stress'} ${i%3+1}</text>`).join('')}<text x="220" y="285">PC1 (Demo)</text><text x="15" y="130" transform="rotate(-90 15 130)">PC2 (Demo)</text></svg>`}
function dashboard(){return title(t('每一次发现，从这里开始','Every discovery starts here'),t('演示工作空间 · 以关联证据推进你的研究','Demo workspace · Advance research through connected evidence'),`<button class="primary" data-action="new-project">＋ ${t('新建演示项目','New demo project')}</button>`)+`<div class="panel intro between"><div><div class="eyebrow">YOUR RESEARCH, CONNECTED</div><h2>${t('从差异变化，走向机制发现','From differential change to mechanistic insight')}</h2><p>${t('选择一个项目，沿五阶段科研流程探索蛋白证据。','Choose a project and follow the five-stage research workflow.')}</p></div><button data-go="/demo/analysis">${t('继续探索示例','Continue demo')} →</button></div>${stats()}<div class="grid-2"><div class="panel"><div class="panel-title between"><h3>${t('最近项目','Recent projects')}</h3><a class="link" href="#/demo/projects">${t('全部项目','View all')} ↗</a></div>${projectRows()}</div><div class="panel panel-pad"><h3>${t('服务连接状态','Service connections')}</h3><div class="config-list" style="margin-top:18px">${['Supabase Auth','PostgreSQL / Private Storage','FastAPI / Redis / Linux Worker'].map(x=>`<div><span>${x}</span>${pending()}</div>`).join('')}</div><p class="note" style="margin-top:15px">${t('演示项目保存在本设备；正式跨设备恢复需要连接服务。','Demo projects are device-local. Cross-device persistence requires configured services.')}</p></div></div>`}
function projectRows(){return projects.map(p=>`<div class="list-row"><div><a class="link" data-project="${esc(p.id)}">${esc(p.name)} ↗</a><p>${esc(p.species)} · ${esc(p.date)} · Demo Data</p></div><button class="ghost" data-delete="${esc(p.id)}" aria-label="Delete demo project">×</button></div>`).join('')||`<div class="empty"><p>${t('尚无演示项目','No demo projects')}</p></div>`}
function projectsPage(){return title(t('我的项目','My projects'),t('独立演示项目管理 · 本设备保存与恢复','Demo project management · Saved on this device'),`<button class="primary" data-action="new-project">＋ ${t('新建演示项目','New demo project')}</button>`)+`<div class="panel"><div class="panel-title between"><h3>${t('全部演示项目','All demo projects')} (${projects.length})</h3>${badge()}</div>${projectRows()}</div>`}
function discoveryContent(){return `<div class="grid-2"><div class="panel panel-pad"><div class="between"><h3>${t('候选关键蛋白','Candidate proteins')}</h3>${badge()}</div><table style="margin-top:16px"><thead><tr><th>#</th><th>Protein</th><th>log₂FC</th><th>${t('证据覆盖','Coverage')}</th></tr></thead><tbody>${[...proteins].sort((a,b)=>Number(saved.has(b[0]))-Number(saved.has(a[0]))).slice(0,5).map((p,i)=>`<tr data-protein="${p[0]}"><td>0${i+1}</td><td>${p[0]} · ${p[1]} ${saved.has(p[0])?'★':''}</td><td>${p[3]}</td><td>${6-i%3} / 7</td></tr>`).join('')}</tbody></table><p class="note" style="margin-top:14px">${t('教学排序：收藏优先，其次固定演示顺序。覆盖数量为示例；未计算综合生物学分数。','Teaching order: saved candidates first, then fixture order. Coverage is illustrative; no biological score computed.')}</p></div><div class="panel panel-pad"><h3>${t('多维证据雷达','Evidence dimensions')}</h3>${radar()}<p class="note">Demo Data · ${t('维度示意，不是实验验证强度或综合分数。','Illustrative dimensions, not validation strength or a composite score.')}</p></div></div><div class="panel panel-pad" style="margin-top:18px"><div class="between"><h3>${t('多维证据矩阵','Evidence matrix')}</h3><a href="#/demo/reports" class="link">${t('生成演示报告','Generate demo report')} →</a></div><div style="overflow:auto"><table class="matrix" style="margin-top:17px"><thead><tr><th>Protein</th>${['Expression','Function','Pathway','Network','Domain','3D','Location'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${proteins.slice(0,5).map((p,i)=>`<tr data-protein="${p[0]}"><td>${p[0]}</td>${Array.from({length:7},(_,j)=>`<td class="${j===5||j===i+2?'no':'yes'}">${j===5||j===i+2?t('缺失','Missing'):t('演示','Demo')}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="note" style="margin-top:15px">${t('来源：Demo fixture v1。真实评价须逐维定义依据、缺失处理与适用范围；预测证据不得视作实验验证。','Source: Demo fixture v1. Production evaluation must define dimension criteria and missing-data handling. Predictions do not equal experimental validation.')}</p></div>`}
function radar(){let pts=(r)=>Array.from({length:7},(_,i)=>{let a=-Math.PI/2+i*Math.PI*2/7;return[180+Math.cos(a)*r,115+Math.sin(a)*r]});return `<svg class="chart" viewBox="0 0 360 240" role="img" aria-label="Demo evidence radar">${[25,50,75].map(r=>`<polygon points="${pts(r).map(p=>p.join(',')).join(' ')}" fill="none" stroke="#dce7ef"/>`).join('')}${pts(75).map(p=>`<path d="M180 115L${p.join(' ')}" stroke="#e3eaf2"/>`).join('')}<polygon points="${pts(75).map((p,i)=>[180+(p[0]-180)*[.9,.8,.7,.9,.65,0,.75][i],115+(p[1]-115)*[.9,.8,.7,.9,.65,0,.75][i]].join(',')).join(' ')}" fill="#2a9b9b20" stroke="#339c9e" stroke-width="2"/>${pts(100).map((p,i)=>`<text x="${p[0]}" y="${p[1]}" text-anchor="middle">${['Expression','Function','Pathway','Network','Domain','3D (missing)','Localization'][i]}</text>`).join('')}</svg>`}
function reportPage(){return title(t('综合科研报告','Integrated research report'),t('关联多维证据 · 区分预测与实验 · 保留缺失信息','Connected evidence · Predictions distinguished from experiments'),`<button class="primary" data-action="export-report">${ic('download')} ${t('下载演示报告 HTML','Download demo HTML')}</button>`)+`<article class="panel report" id="report-body">${badge()}<div class="eyebrow">Cy_Omics_v2.0 · INTEGRATED PROTEOMICS RESEARCH REPORT</div><h1>${esc(project?.name||'Demo project')}</h1><p style="margin-top:15px">${t('综合蛋白质组学分析报告 · 教学演示版','Integrated proteomics analysis report · Demonstration')}</p><hr style="border:0;border-top:1px solid #e5ecf4;margin:25px 0"><h2>01　${t('研究设计与定量概览','Study design & quantification')}</h2><p>${t('演示设计：拟南芥干旱胁迫，Control 与 Stress 各 3 个重复。5,842 个蛋白，599 个差异蛋白（312 上调、287 下调）。这些数值为演示记录，不是实际计算。','Illustrative Arabidopsis drought study: three replicates per group. Fixture counts: 5,842 proteins, 599 DEPs (312 up, 287 down). These are demo values, not analysis results.')}</p><h2>02　${t('功能与网络证据','Functional & network evidence')}</h2><p>${t('示例证据链关联氧化应激、过氧化物酶功能与网络候选节点。演示中的注释与互作不构成经数据库验证的证据。','The example connects oxidative stress, peroxidase function and candidate network nodes. Demo annotations and interactions are not database-verified evidence.')}</p><h2>03　${t('结构与空间证据','Structural & spatial evidence')}</h2><p>${t('当前没有真实 AlphaFold 模型、PDB 实验结构或定位预测结果；结构丝带和结构域图均为示意。三维结构证据列为缺失。','No real AlphaFold model, PDB experimental structure or localization result is available. Ribbons and domains are illustrations. 3D evidence is missing.')}</p><h2>04　${t('候选与可验证假设','Candidates & testable hypotheses')}</h2><p>${t('演示候选：','Demo candidates: ')}${[...saved].map(esc).join(', ')||'AT1G56600 (PRX12)'}. ${t('可提出与氧化应激响应相关的工作假设；须以真实定量、通路、互作与独立实验进一步检验，不能据此作因果结论。','A working oxidative-stress hypothesis requires real quantification, pathway and interaction analysis plus independent experiments; no causal conclusion follows.')}</p><h2>05　${t('方法、来源与限制','Methods, provenance & limitations')}</h2><p>Demo fixture v1 · ${t('未执行计算，无实际软件或数据库运行版本。正式结果应补齐任务 ID、输入校验和、参数、软件/数据库版本、执行时间与证据类型。','No computations executed. Production reports must include task IDs, checksums, parameters, software/database versions, timestamps and evidence types.')}</p></article>`}
function tasksPage(){return title(t('我的分析任务','My analysis tasks'),t('Queued · Running · Succeeded · Failed · Cancelled','Queued · Running · Succeeded · Failed · Cancelled'),pending())+`<div class="panel"><div class="panel-title between"><h3>${t('任务列表','Task list')}</h3><button data-action="refresh">${t('刷新状态','Refresh')}</button></div><div class="empty">${ic('task')}<h3>${t('尚未连接计算任务服务','Compute task service not connected')}</h3><p>${t('当前没有真实任务。提交分析会显示待接入提示，不会伪造任务 ID、进度或结果。','No real tasks exist. Submissions show a not-connected message; no task IDs, progress or results are fabricated.')}</p><button data-action="cancel-task">${t('任务取消接口说明','Cancellation contract')}</button></div></div><div class="panel panel-pad" style="margin-top:18px"><h3>${t('状态与操作约定','Status & action contract')}</h3><table style="margin-top:14px"><thead><tr><th>Status</th><th>${t('说明','Meaning')}</th><th>${t('可取消','Cancellable')}</th></tr></thead><tbody>${[['Queued','等待资源 / Waiting for resources','Yes'],['Running','Worker 执行中 / Executing','Yes, acknowledgement required'],['Succeeded','结果已归档 / Results stored','No'],['Failed','记录脱敏错误 / Sanitized error','No'],['Cancelled','Worker 已确认取消 / Worker acknowledged','No']].map(x=>`<tr>${x.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function collaboration(){return title(t('项目协作与访问控制','Project collaboration & access'),t('默认私有 · Owner / Editor / Viewer','Private by default · Owner / Editor / Viewer'),`<button class="primary" data-action="invite">${ic('mail')} ${t('邀请协作者','Invite collaborator')}</button>`)+`<div class="grid-2"><div class="panel panel-pad"><h3>${t('成员与邀请','Members & invitations')}</h3><div class="empty"><p>${t('演示空间无真实成员。邀请与撤销需要经过后端权限检查及邮件服务。','No real members in demo mode. Invitations and revocation require backend authorization and email service.')}</p>${pending()}</div></div><div class="panel panel-pad"><h3>${t('项目角色','Project roles')}</h3>${[['Owner','项目、数据、任务、成员与删除 / Full project administration'],['Editor','编辑与运行分析 / Edit and run analyses'],['Viewer','查看授权结果 / View authorized results']].map(x=>`<div class="list-row"><b>${x[0]}</b><small>${x[1]}</small></div>`).join('')}</div></div><div class="panel empty" style="margin-top:18px"><h3>${t('操作审计与访问记录','Audit & access history')}</h3><p>${t('待接入后端审计。此处不生成虚构的用户访问记录。','Backend audit service not connected. No fabricated access records are shown.')}</p></div>`}
function account(){return title(t('用户账户管理','Account settings'),t('邮箱验证、会话与私人数据由正式认证服务管理','Email verification, sessions and private data require configured authentication'))+`<div class="grid-2"><div class="panel panel-pad stack"><h3>${t('演示访客','Demo visitor')}</h3><p class="note">${t('当前没有登录真实账户，也没有收集个人资料。','You are not signed into a real account. No profile has been collected.')}</p><button class="primary" data-go="/login">${t('前往邮箱登录','Email sign in')}</button><button data-go="/forgot-password">${t('重置密码','Reset password')}</button><button data-action="logout">${t('退出演示空间','Leave demo workspace')}</button></div><div class="panel panel-pad stack"><h3>${t('数据管理','Data controls')}</h3><p class="note">${t('此处仅导出演示项目和文件元数据。正式账户导出与删除需要验证身份并由后端执行。','These actions export only demo projects and metadata. Production export and erasure require verified backend authorization.')}</p><button data-action="export-data">${t('导出本机演示数据','Export local demo data')}</button><button data-action="clear-demo">${t('删除本机演示数据','Delete local demo data')}</button></div></div>`}
function admin(){return title(t('平台管理员后台','Platform administration'),t('系统角色由服务端授予，项目所有者不自动拥有管理员权限。','Platform roles are server-assigned. Project owners are not automatically administrators.'))+`<div class="panel empty">${ic('lock')}<h3>${t('管理员身份尚未验证','Administrator identity not verified')}</h3><p>${t('用户、项目、计算队列、资源配额、系统健康、备份和审计管理将在正式服务接入并验证管理员权限后开放。','User management, project oversight, compute queues, quotas, health, backups and audit require a verified platform administrator.')}</p>${pending()}</div>`}
function dataPage(){return title(t('数据管理','Data management'),t('演示文件校验与本机元数据记录 · 原始文件不上传','Demo validation and local metadata · No original files uploaded'))+`<div class="panel panel-pad stack">${uploadPanel()}</div><div class="panel" style="margin-top:18px"><div class="panel-title"><h3>${t('本机演示文件记录','Local demo file records')}</h3></div>${files.map((f,i)=>`<div class="list-row"><div><b>${esc(f.name)}</b><p>${(f.size/1024).toFixed(1)} KB · ${esc(f.type)} · ${f.count} records · ${esc(f.projectId)}</p></div><button data-file-delete="${i}">×</button></div>`).join('')||`<div class="empty"><p>${t('尚未选择演示文件','No demo file selected')}</p></div>`}</div>`}
function help(){return `<div class="panel panel-pad"><h2>${t('使用指南与帮助中心','Guide & help center')}</h2>${[[t('如何开始？','How do I start?'),t('先进入演示项目体验五阶段工作流。正式注册需要接入 Supabase Auth、验证邮箱及正式邮件服务。','Explore the demo project first. Real registration requires configured Supabase Auth and verified email delivery.')],[t('如何连接自己的数据？','How do I connect data?'),t('原型只校验演示文件，不上传。真实数据通过 FastAPI 签名上传到私有存储，并绑定项目与用户。','The prototype validates local demo files only. Production data uses FastAPI-authorized uploads to private storage.')],[t('蛋白身份如何关联？','How are proteins linked?'),t('各页面统一引用物种、来源、Accession、Isoform 和序列 SHA256；点击蛋白 ID、通路或网络节点探索关联。','All modules share species, source, accession, isoform and sequence SHA256. Click proteins, pathways and network nodes to explore.')],[t('为什么无法提交任务？','Why can I not submit tasks?'),t('Linux Worker 与 FastAPI 尚未连接。平台明确拒绝伪造分析成功，待配置后再开放。','FastAPI and Linux Workers are not connected. The platform does not fabricate successful results.')],[t('我的项目在哪里保存？','Where are projects stored?'),t('当前演示项目仅保存于本浏览器。本机演示不是私人多用户数据存储；正式持久化由 PostgreSQL 负责。','Demo projects live only in this browser. Production multi-user persistence will use PostgreSQL.')]].map(x=>`<details class="faq"><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}<div class="row" style="margin-top:22px"><button data-go="/contact">${t('联系技术支持','Contact support')} →</button><button data-go="/features">${t('浏览全部功能','All features')} →</button></div></div>`}
function loginPage(){return `<div class="portal">${publicNav()}<main class="auth-page"><section class="panel auth-card"><div class="eyebrow">Cy_Omics_v2.0 ACCOUNT</div><h1>${t('欢迎回到科研工作空间','Welcome back to your workspace')}</h1><p>${t('邮箱认证 · 私有项目 · 可追溯研究','Email authentication · Private projects · Traceable research')}</p><div data-auth-status></div><form id="auth-form" novalidate><label class="field">${t('邮箱','Email')}<input required type="email" name="email" id="login-email" autocomplete="email" placeholder="researcher@institution.edu" aria-describedby="login-email-error"><span class="signup-field-error" id="login-email-error" data-login-error="email"></span></label><label class="field">${t('密码','Password')}<span class="signup-password-control"><input required type="password" name="password" id="login-password" autocomplete="current-password" placeholder="${t('输入注册时设置的密码','Enter the password you set when registering')}" aria-describedby="login-password-help login-password-error"><button type="button" class="signup-password-toggle" data-login-toggle aria-controls="login-password" aria-pressed="false" aria-label="${t('显示密码','Show password')}"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/><path class="signup-eye-slash" d="m4 3 16 18"/></svg></button></span><small class="note" id="login-password-help">${t('输入注册时设置的密码，保留原有空格。','Enter the password you set when registering, preserving any spaces.')}</small><span class="signup-field-error" id="login-password-error" data-login-error="password"></span></label><div class="signup-state" data-login-state role="status" aria-live="polite" aria-atomic="true"></div><a class="primary" data-login-projects href="#/workspace/projects" hidden>${t('进入私人项目','Enter private projects')}</a><button type="submit" class="primary" data-login-submit disabled>${t('邮箱密码登录','Sign in with email')}</button><div class="row"><button type="button" class="link" data-login-recheck>${t('重新检查登录状态','Recheck sign-in status')}</button><button type="button" class="link" data-login-logout hidden>${t('退出此浏览器会话','Sign out of this browser')}</button></div></form><div class="banner">${t('登录信息由服务器管理。私人项目需登录后访问，分析功能按模块逐步开放。','Sign-in is managed by the server. Sign in to access private projects; analysis features are enabled module by module.')}</div><div class="auth-foot"><a href="#/register">${t('创建新账户','Create an account')}</a>　·　<a href="#/forgot-password">${t('忘记密码','Forgot password')}</a><br><br><a href="#/demo/analysis" class="link">${t('无需登录，探索独立演示空间','Explore the isolated demo without signing in')} →</a></div></section></main>${footer()}</div>`}
function authPage(type){const showStatus=['/login','/register'].includes(route);let register=type==='register',forgot=type==='forgot-password',reset=type==='reset-password';let name=register?t('创建科研账户','Create your research account'):forgot?t('找回密码','Recover your password'):reset?t('重置密码','Reset your password'):t('欢迎回到科研工作空间','Welcome back to your workspace');return `<div class="portal">${publicNav()}<main class="auth-page"><section class="panel auth-card"><div class="eyebrow">Cy_Omics_v2.0 ACCOUNT</div><h1>${name}</h1><p>${t('邮箱认证 · 私有项目 · 可追溯研究','Email authentication · Private projects · Traceable research')}</p>${showStatus?'<div data-auth-status></div>':''}<form id="auth-form"${register?' novalidate':''}>${register?`<label class="field">${t('姓名','Full name')}<input disabled name="name" autocomplete="off" maxlength="100"></label>`:''}${!reset?`<label class="field">${t('邮箱','Email')}<input required type="email" name="email" autocomplete="email" placeholder="researcher@institution.edu"${register?' id="signup-email" aria-describedby="signup-email-error"':''}>${register?'<span class="signup-field-error" id="signup-email-error" data-signup-error="email"></span>':''}</label>`:''}${!forgot?`<label class="field">${t('密码','Password')}${register?'<span class="signup-password-control">':''}<input required type="password" name="password" minlength="12" autocomplete="${register||reset?'new-password':'current-password'}" placeholder="${t('至少 12 位','At least 12 characters')}"${register?' id="signup-password" aria-describedby="signup-password-help signup-password-error"':''}>${register?`<button type="button" class="signup-password-toggle" data-signup-toggle aria-controls="signup-password" aria-pressed="false" aria-label="${t('显示密码','Show password')}"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/><path class="signup-eye-slash" d="m4 3 16 18"/></svg></button></span><small class="note" id="signup-password-help">${t('密码至少 12 个字符；过长时请缩短。','Use at least 12 characters; shorten the password if it is too long.')}</small><span class="signup-field-error" id="signup-password-error" data-signup-error="password"></span>`:''}</label>`:''}${register?`<div class="form-grid"><label class="field">${t('机构（可选）','Institution (optional)')}<input disabled name="institution" autocomplete="off" maxlength="200"></label><label class="field">${t('研究领域（可选）','Research field (optional)')}<input disabled name="field" autocomplete="off" maxlength="100"></label><label class="field full">${t('国家 / 地区（可选）','Country / region (optional)')}<input disabled name="country" autocomplete="off" maxlength="100"></label></div><p class="note signup-profile-note">${t('姓名、机构、研究领域和国家 / 地区暂不可填写、不采集，资料功能将在后续开放。','Name, institution, research field and country/region are disabled and not collected. Profile editing will be available in a later update.')}</p><label class="note"><input type="checkbox" name="terms" id="signup-terms" aria-describedby="signup-terms-error"> ${t('我同意','I agree to')} <a href="#/terms" class="link">${t('服务条款','Terms')}</a> ${t('和','and')} <a href="#/privacy" class="link">${t('隐私政策','Privacy Policy')}</a></label><span class="signup-field-error" id="signup-terms-error" data-signup-error="terms"></span><div class="signup-state" data-signup-state role="status" aria-live="polite" aria-atomic="true"></div>`:''}<button class="primary"${register?' type="submit"':''}>${register?t('注册并验证邮箱','Register & verify email'):forgot?t('发送重置链接','Send reset link'):reset?t('设置新密码','Set new password'):t('邮箱密码登录','Sign in with email')}</button></form><div class="banner">${register?t('注册请求仅提交至本平台，能否注册及验证须以服务端结果为准。验证邮箱后可前往登录页继续。','Registration requests are sent only to this platform. Registration and verification depend on the server response. After verifying your email, continue on the sign-in page.'):showStatus?t('邮箱注册与登录尚未启用，此页面不会提交或保存密码。','Email registration and sign-in are not enabled. This page does not submit or save passwords.'):t('认证服务待配置。此表单不会提交、保存密码或创建模拟会话。完成 Supabase 与邮件配置后启用真实邮箱认证。','Authentication is not configured. This form does not submit or store passwords or create simulated sessions. Supabase and email configuration are required.')}</div><div class="auth-foot">${register?`<a href="#/login">${t('已有账户？前往登录','Already registered? Sign in')}</a>`:`<a href="#/register">${t('创建新账户','Create an account')}</a>　·　<a href="#/forgot-password">${t('忘记密码','Forgot password')}</a>`}<br><br><a href="#/demo/analysis" class="link">${t('无需登录，探索独立演示空间','Explore the isolated demo without signing in')} →</a></div></section></main>${footer()}</div>`}
function infoPage(kind){let content='';if(kind==='workflow')content=`<div class="section-head"><div class="eyebrow">DISCOVERY → BIOLOGICAL INSIGHT</div><h1>${t('五阶段科研分析主线','Five-stage research workflow')}</h1><p class="muted" style="margin-top:15px">${t('从同一项目、同一批蛋白质出发，逐步建立可追溯的科研证据链。点击任一阶段进入交互演示。','Build a traceable evidence chain around one project and one protein identity. Open any stage to explore the demo.')}</p></div>${publicStages()}`;else if(kind==='features')content=title(t('完整的蛋白质组学证据工具','A complete proteomics evidence toolkit'),t('所有工具围绕项目与统一蛋白身份关联','All tools connect through projects and unified protein identity'))+`<div class="tool-grid">${tools.map(toolCard).join('')}</div>`;else if(['guide','help'].includes(kind))content=help();else if(kind==='hub-intro'||kind==='discovery-intro')content=`<div class="eyebrow">${kind==='hub-intro'?'PROTEIN KNOWLEDGE HUB':'KEY PROTEIN DISCOVERY'}</div><h1>${t(kind==='hub-intro'?'所有证据，回到同一个蛋白质':'让关键候选的每一维依据清晰可见',kind==='hub-intro'?'Every evidence, connected to one protein':'Make every candidate evidence dimension visible')}</h1><p class="muted" style="margin:25px 0">${t('关联表达、功能、通路、互作、结构域、三维结构与亚细胞定位；记录来源、置信度和缺失项。预测与实验始终清晰区分。','Connect expression, function, pathways, interactions, domains, structure and localization. Track provenance, confidence and missing evidence. Distinguish prediction from experiment.')}</p><button class="primary" data-go="/demo/${kind==='hub-intro'?'hub':'discovery'}">${t('打开交互演示','Open interactive demo')} →</button>`;else if(kind==='about')content=`<div class="eyebrow">ABOUT Cy_Omics_v2.0</div><h1>${t('围绕科研问题，连接蛋白质证据','Connect protein evidence around research questions')}</h1><p style="margin-top:25px" class="muted">${t('Cy_Omics_v2.0 是面向全球科研人员的独立综合蛋白质组学分析平台。将定量、差异发现、功能解释、网络分析与结构证据组织为完整科研流程，以统一 Protein Knowledge Hub 为中心形成可验证的机制假设。当前版本为未部署的交互原型，真实认证和计算服务待接入。','Cy_Omics_v2.0 is an independent integrated proteomics research platform for global researchers. It connects quantification, differential discovery, functional interpretation, network analysis and structural evidence through a unified Protein Knowledge Hub. This version is an unpublished interactive prototype; authentication and compute services are not connected.')}</p>`;else content=legal(kind);return `<div class="portal">${publicNav()}<main class="${kind==='features'||kind==='workflow'?'portal-section':'legal'}">${content}</main>${footer()}</div>`}
function legal(k){const names={privacy:['隐私政策','Privacy policy'],terms:['用户服务条款','Terms of service'],'data-policy':['数据使用说明','Data use policy'],contact:['联系和技术支持','Contact & technical support']};let n=names[k]||['页面未找到','Page not found'];return `<div class="eyebrow">${t('运营草案 · 发布前须补全','OPERATIONAL DRAFT · COMPLETE BEFORE RELEASE')}</div><h1>${t(...n)}</h1><div class="banner">${t('本页为产品原型草案，不代表已生效的正式运营承诺。','Prototype draft, not a finalized operational commitment.')}</div>${k==='contact'?`<h2>${t('技术支持渠道待配置','Support channel not configured')}</h2><p>${t('运营主体与正式支持邮箱尚未提供。当前不收集或发送支持信息。请在上线前配置联系邮箱、响应范围与安全漏洞报告渠道。','Operator and support email have not been supplied. No support messages are collected or sent. Configure contact details, support scope and vulnerability reporting before launch.')}</p>`:`<h2>${t('研究数据与访问','Research data & access')}</h2><p>${t('正式平台项目默认私有，仅项目所有者与已授权成员访问。演示版本仅在本浏览器保留演示项目及文件元数据，不上传原始研究数据。','Production projects are private by default and accessible only to owners and authorized members. This demo stores only local demo projects and metadata; original research data is not uploaded.')}</p><h2>${t('账户与使用责任','Accounts & responsible use')}</h2><p>${t('正式账户须通过邮箱验证。用户应拥有所上传数据的处理权限；科研输出需要专业审阅，计算关联和预测不构成实验验证。','Production accounts require verified email. Users must have authority to process submitted data. Research outputs require professional review; predictions and computational associations are not experimental validation.')}</p><h2>${t('导出、删除与保留','Export, erasure & retention')}</h2><p>${t('演示数据可在账户设置中导出和清除。正式数据的保留期限、备份删除、处理地区、运营主体与隐私联系人需由运营方确定后补全。','Demo data can be exported or cleared in account settings. Production retention periods, backup erasure, processing regions, operator identity and privacy contacts must be finalized by the operator.')}</p><h2>${t('需要补全的运营信息','Operational details to finalize')}</h2><p>${t('运营主体、法域、支持邮箱、数据驻留、服务可用性、资源配额、费用与研究数据授权条款均未配置。默认不将私人研究数据用于训练或公开分享；任何未来用途须另行取得明确授权。','Operator, jurisdiction, support email, residency, availability, quotas, pricing and data licensing are not configured. Private research data is not intended for public sharing or training by default; additional uses require explicit authorization.')}</p>`}`}
function emptyPage(){return `<div class="panel empty"><h3>${t('页面未找到','Page not found')}</h3><button data-go="/">${t('返回首页','Return home')}</button></div>`}
function proteinPage(){
  let id;
  try { id=decodeURIComponent(route.split('/')[3]||''); } catch { id=''; }
  const protein=proteins.find(p=>p[0]===id);
  if(!protein)return title('Protein Knowledge Hub',t('未找到请求的蛋白质','Requested protein not found'))+`<section class="panel empty"><h2>${t('蛋白不存在','Protein not found')}</h2><p>${t('该蛋白 ID 不存在，请返回知识中心选择有效蛋白。','This protein ID does not exist. Return to the Knowledge Hub to select a valid protein.')}</p><button data-go="/demo/hub">${t('返回 Protein Knowledge Hub','Back to Protein Knowledge Hub')}</button></section>`;
  selected=protein;
  return title('Protein Knowledge Hub',selected[0])+proteinDetail();
}
function privateProjectsPage(){return `<div class="portal">${publicNav()}<main class="content" style="max-width:1100px;margin:0 auto"><div class="breadcrumb">${t('私人工作空间','Private workspace')}<span>/</span>${t('我的项目','My projects')}</div><div id="private-projects"></div></main>${footer()}</div>`}
function render(){disposePrivateProjectView?.();disposePrivateProjectView=null;disposeLoginView?.();disposeLoginView=null;disposeSignupView?.();disposeSignupView=null;disposeAuthStatusView?.();disposeAuthStatusView=null;disposeAssociationUI?.();disposeAssociationUI=null;cancelLocalPreview();route=location.hash.slice(1)||'/';authStatusRoutes.enter(route);signupRoutes.enter(route);loginRoutes.enter(route);privateProjectRoutes.enter(route);let body='';if(route==='/workspace/projects')body=privateProjectsPage();else if(route==='/login')body=loginPage();else if(route.startsWith('/workspace'))body=authPage('login');else if(route.startsWith('/demo')){if(!project)project=projects[0];let k=route.split('/')[2];body=shell(k==='analysis'||!k?analysis():k==='stage'?stagePage(Math.max(0,Math.min(4,Number(route.split('/')[3])||0))):k==='tool'?toolPage(route.split('/')[3]):k==='dashboard'?dashboard():k==='projects'?projectsPage():k==='hub'?title('Protein Knowledge Hub',t('统一蛋白身份 · 关联全部科研证据','Unified protein identity · Connected research evidence'))+`<div class="lower" style="margin-top:0">${proteinList()}${proteinDetail()}</div>`:k==='protein'?proteinPage():k==='discovery'?title('Key Protein Discovery',t('透明比较依据、覆盖和缺失信息','Transparent evidence, coverage and missing dimensions'))+discoveryContent():k==='reports'?reportPage():k==='tasks'?tasksPage():k==='collaboration'?collaboration():k==='account'?account():k==='admin'?admin():k==='data'?dataPage():k==='help'?help():emptyPage())}else if(['/login','/register','/forgot-password','/reset-password'].includes(route))body=authPage(route.slice(1));else body=route==='/'?portal():infoPage(route.slice(1));if(['/demo/tool/import','/demo/data'].includes(route)){
 body=body.replace(/<div class="breadcrumb">.*?<\/div>/,'<div class="breadcrumb">Cy_Omics_v2.0 <span>/</span>'+t('本地数据工作空间','Local data workspace')+'</div>');
 body=body.replace('<span class="badge demo">Demo Data</span>','<span class="badge">'+t('本地只读','Local read-only')+'</span>');
 body=body.replace('当前为独立演示空间，所有图表和注释仅供交互体验，请勿上传真实研究数据。','真实文件仅在本页内存中预览与关联，不上传、不持久化、不执行科研计算。其他演示模块不使用此输入。');
 body=body.replace('Isolated demo workspace. All charts and annotations are illustrative. Do not upload real research data.','Real files stay in page memory for preview and association only. No upload, persistence, compute or demo linkage.');
 body=body.replace('演示模式 · 仅本设备保存','本地预览 · 原始内容不保存');
}$('#app').innerHTML=body;document.documentElement.lang=en?'en':'zh-CN';bind();}
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal();$('#modal').querySelector('[data-close]')?.addEventListener('click',()=>$('#modal').close())}
function newProject(){modal(`<h2>${t('新建演示项目','Create demo project')}</h2><form id="project-form"><label class="field">${t('项目名称','Project name')}<input name="name" required maxlength="80" placeholder="My_Proteomics_Project"></label><label class="field">${t('物种','Species')}<input name="species" required maxlength="100" value="Arabidopsis thaliana"></label><label class="field">${t('研究描述','Description')}<textarea name="desc" maxlength="300"></textarea></label><p class="note">${t('本机演示项目。创建后关联的图表仍为固定 Demo Data，不会推断为你的研究结果。','Device-local demo project. Charts remain fixed Demo Data and do not represent your research.')}</p><div class="actions"><button type="button" data-close>${t('取消','Cancel')}</button><button class="primary">${t('创建演示项目','Create demo project')}</button></div></form>`);$('#project-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);let name=f.get('name').trim();if(!name)return;project={id:crypto.randomUUID(),name,species:f.get('species').trim(),desc:f.get('desc').trim(),samples:0,date:new Date().toISOString().slice(0,10)};projects.push(project);persist();$('#modal').close();render();toast(t('演示项目已保存到本设备','Demo project saved on this device'))}}
function pathway(i){modal(`<div class="between"><h2>${t('通路关联蛋白','Pathway-linked proteins')}</h2>${badge()}</div><p class="note">${goTerms[i%8]} · ${t('演示关联，未执行富集检验','Illustrative association; no enrichment test executed')}</p><div style="margin:20px 0">${proteins.filter((_,j)=>(i+j)%3!==0).slice(0,5).map(p=>`<div class="list-row"><button class="link" data-modal-protein="${p[0]}">${p[0]} · ${p[1]} ↗</button><span class="${p[3]>0?'up':'down'}">${p[3]}</span></div>`).join('')}</div><button data-close>${t('关闭','Close')}</button>`);$$('[data-modal-protein]').forEach(x=>x.onclick=()=>{$('#modal').close();selected=proteins.find(p=>p[0]===x.dataset.modalProtein);go('/demo/protein/'+selected[0])})}
function download(name,content,type){let a=document.createElement('a');let url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function readFile(file){
  cancelLocalPreview();
  const readId=localPreviewRead, box=$('#file-result'), preview=$('#protein-groups-preview'), input=$('#file-input');
  if(!box||!preview||!input)return;
  preview.replaceChildren();
  box.textContent='';
  const active=()=>readId===localPreviewRead&&box.isConnected&&preview.isConnected;
  const fail=message=>{if(active()){preview.replaceChildren();box.textContent=message;toast(message)}};
  let reader;
  try {
    if(!file)return;
    const ext=file.name.split('.').pop().toLowerCase(), isFasta=['fasta','fa'].includes(ext);
    if(!['txt','csv','tsv','fasta','fa'].includes(ext))return fail(t('不支持的文件类型','Unsupported file type'));
    const limit=(isFasta?25:10)*1024*1024;
    if(file.size>limit)return fail(t(`文件超过 ${isFasta?25:10} MiB 限制`,`File exceeds ${isFasta?25:10} MiB limit`));
    if(isFasta){
      // Read-only preview: no per-sequence SHA-256 or demo persistence.
      const parser=createFastaPreviewParser(), decoder=new TextDecoder('utf-8',{fatal:true});
      reader=file.stream().getReader();
      localPreviewReader=reader;
      let bytes=0;
      box.textContent=t('正在本地读取 FASTA 并检查结构…','Reading FASTA locally and checking structure…');
      while(active()){
        const {done,value}=await reader.read();
        if(!active())return;
        if(done)break;
        bytes+=value.byteLength;
        if(bytes>limit)return fail(t('文件超过 25 MiB 限制','File exceeds 25 MiB limit'));
        parser.push(decoder.decode(value,{stream:true}));
      }
      if(!active())return;
      parser.push(decoder.decode());
      const result=parser.finish();
      preview.innerHTML=fastaPreview(result);
      box.textContent=t('FASTA 结构检查通过；仅内存预览，未保存、未上传、未分析。','FASTA structure checks passed; memory-only preview, not saved, uploaded or analyzed.');
      return;
    }
    const text=await file.text();
    if(!active())return;
    if(ext==='txt'){
      const result=parseProteinGroups(text);
      mountProteinGroupsPreview(preview,result);
      box.textContent=t('TXT 校验通过；仅内存预览，未保存、未上传、未分析。','TXT validated; memory-only preview, not saved, uploaded or analyzed.');
      return;
    }
    if(text.includes('\0'))return fail(t('文件含二进制内容，已拒绝','Binary content rejected'));
    const lines=text.trim().split(/\r?\n/), delimiter=ext==='csv'?',':'\t';
    if(lines.length<2||!lines[0].includes(delimiter))return fail(t('表格需含表头与至少一行分隔数据','A header and at least one delimited row are required'));
    const count=lines.length-1;
    files.push({name:file.name,size:file.size,type:ext,count,hashes:[],projectId:project?.id||'demo'});
    persist();
    box.textContent=t(`本机校验完成：${count} 条记录。未上传、未执行分析。`,`Local validation: ${count} records. Not uploaded or analyzed.`);
    toast(t('演示文件元数据已保存','Demo file metadata saved'));
  } catch(error) {
    const ext=file?.name.split('.').pop().toLowerCase();
    if(error instanceof FastaPreviewError){
      fail(t(`FASTA 结构检查失败：${error.code}（行 ${error.line}）。`,`FASTA structure check failed: ${error.code} (line ${error.line}).`));
    }else if(['fasta','fa'].includes(ext)){
      fail(t('FASTA UTF-8 解码或读取失败，未生成预览。','FASTA UTF-8 decoding or reading failed; no preview created.'));
    }else fail(error.message||t('文件读取失败，未生成预览。','File read failed; no preview created.'));
  } finally {
    if(localPreviewReader===reader)localPreviewReader=null;
    if(reader){
      try{await reader.cancel()}catch{}
      reader.releaseLock();
    }
    if(active())input.value='';
  }
}
function bind(){const privateRoot=$('#private-projects');if(privateRoot)disposePrivateProjectView=mountPrivateProjects(privateRoot,privateProjectRoutes.current(),t);const loginForm=route==='/login'?$('#auth-form'):null;if(loginForm)disposeLoginView=mountLogin(loginForm,loginRoutes.current(),t);const signupForm=route==='/register'?$('#auth-form'):null;if(signupForm)disposeSignupView=mountSignup(signupForm,signupRoutes.current(),t);const authStatusRoot=$('[data-auth-status]');if(authStatusRoot)disposeAuthStatusView=mountAuthStatus(authStatusRoot,authStatusRoutes.current(),t);const unifiedRoot=$('#unified-import');if(unifiedRoot)disposeAssociationUI=mountImportWorkspace(unifiedRoot,t,(file,count)=>{files.push({name:file.name,size:file.size,type:file.name.split('.').pop().toLowerCase(),count,hashes:[],projectId:project?.id||'demo'});persist()});const associationRoot=$('#protein-association');if(associationRoot)disposeAssociationUI=mountProteinAssociation(associationRoot,t);$$('[data-go]').forEach(x=>x.onclick=()=>go(x.dataset.go));$$('[data-protein]').forEach(x=>{const f=()=>{selected=proteins.find(p=>p[0]===x.dataset.protein)||selected;proteinTab='overview';if(route.includes('/analysis')||route.includes('/hub')||route.includes('/tool/')){render();}else go('/demo/protein/'+selected[0])};x.onclick=f;x.onkeydown=e=>{if(e.key==='Enter')f()}});$$('[data-term]').forEach(x=>x.onclick=()=>pathway(Number(x.dataset.term)));$$('[data-ptab]').forEach(x=>x.onclick=()=>{proteinTab=x.dataset.ptab;render()});$$('[data-chart]').forEach(x=>x.onclick=()=>{chartTab=x.dataset.chart;render()});$$('[data-project]').forEach(x=>x.onclick=()=>{project=projects.find(p=>p.id===x.dataset.project);go('/demo/analysis')});$$('[data-delete]').forEach(x=>x.onclick=()=>{let id=x.dataset.delete;modal(`<h2>${t('删除本机演示项目？','Delete local demo project?')}</h2><p>${t('项目与其文件元数据将从本浏览器移除。','The project and its file metadata will be removed from this browser.')}</p><div class="actions"><button data-close>${t('取消','Cancel')}</button><button id="confirm-delete">${t('删除','Delete')}</button></div>`);$('#confirm-delete').onclick=()=>{projects=projects.filter(p=>p.id!==id);files=files.filter(f=>f.projectId!==id);if(project?.id===id)project=projects[0];persist();$('#modal').close();render()}});$$('[data-file-delete]').forEach(x=>x.onclick=()=>{files.splice(Number(x.dataset.fileDelete),1);persist();render()});$('#protein-search')?.addEventListener('input',e=>{let pos=e.target.selectionStart;search=e.target.value;render();$('#protein-search').focus();$('#protein-search').setSelectionRange(pos,pos)});$('#tool-protein')?.addEventListener('change',e=>{selected=proteins.find(p=>p[0]===e.target.value);render()});$('#file-input')?.addEventListener('change',e=>readFile(e.target.files[0]));$('#dropzone')?.addEventListener('dragover',e=>e.preventDefault());$('#dropzone')?.addEventListener('drop',e=>{e.preventDefault();readFile(e.dataTransfer.files[0])});if(!['/register','/login'].includes(route))$('#auth-form')?.addEventListener('submit',e=>{e.preventDefault();e.target.querySelector('[name=password]')?.value&&(e.target.querySelector('[name=password]').value='');toast(['/login','/register'].includes(route)?t('邮箱注册与登录尚未启用：未发送请求、未创建账户或会话。','Email registration and sign-in are not enabled: no request, account or session created.'):t('认证服务未配置：未发送请求、未创建账户或会话。','Authentication not configured: no request, account or session created.'))});$$('[data-action]').forEach(x=>x.onclick=()=>action(x.dataset.action))}
function action(a){if(a==='lang'){en=!en;localStorage.setItem('pp-lang',en?'en':'zh');render()}else if(a==='menu')$('.sidebar').classList.toggle('open');else if(a==='new-project')newProject();else if(a==='candidate'){saved.has(selected[0])?saved.delete(selected[0]):saved.add(selected[0]);persist();render();toast(t('演示候选集已更新','Demo candidate set updated'))}else if(a==='filter'){let f=Number($('#fc').value),p=Number($('#pvalue').value);if(!Number.isFinite(f)||f<0||!Number.isFinite(p)||p<0||p>1)return toast(t('请输入有效筛选阈值','Enter valid thresholds'));fc=f;pval=p;render();toast(t('已应用演示筛选；未执行统计计算','Demo filters applied; no statistical computation'))}else if(a==='run')toast(t('FastAPI / Linux Worker 待接入，未提交真实任务。','FastAPI / Linux Worker not connected. No task submitted.'));else if(a==='refresh')toast(t('任务服务未配置，无法查询真实状态。','Task service not configured; no real status available.'));else if(a==='cancel-task')toast(t('接入后将通过 POST /tasks/{id}/cancel 请求取消，并等待 Worker 确认。','Configured service uses POST /tasks/{id}/cancel and waits for Worker acknowledgement.'));else if(a==='notifications')toast(t('当前无真实通知；服务连接尚未配置。','No real notifications. Services are not configured.'));else if(a==='logout')go('/');else if(a==='export-report'){download('Cy_Omics_v2.0-Demo-Report.html','<!doctype html><meta charset="utf-8"><title>Cy_Omics_v2.0 · Demo Research Report</title><style>body{font:15px/1.8 sans-serif;max-width:900px;margin:50px auto;padding:20px;color:#17334d}h2{margin-top:35px}.demo{color:#a56a13}</style>'+$('#report-body').outerHTML,'text/html');toast(t('演示报告已导出','Demo report exported'))}else if(a==='export-data')download('Cy_Omics_v2.0-Demo-Data.json',JSON.stringify({mode:'Demo Data - device-local only',projects,files,candidates:[...saved]},null,2),'application/json');else if(a==='clear-demo'){modal(`<h2>${t('清除全部本机演示数据？','Clear all local demo data?')}</h2><p>${t('将删除演示项目、文件元数据和候选集。','Demo projects, file metadata and candidate sets will be deleted.')}</p><div class="actions"><button data-close>${t('取消','Cancel')}</button><button id="clear-confirm">${t('确认清除','Confirm')}</button></div>`);$('#clear-confirm').onclick=()=>{projects=[];files=[];saved.clear();project=undefined;persist();$('#modal').close();render()}}else if(a==='invite'){modal(`<h2>${t('邀请项目协作者','Invite project collaborator')}</h2><form id="invite-form"><label class="field">${t('协作者邮箱','Collaborator email')}<input type="email" required></label><label class="field">${t('角色','Role')}<select><option>Viewer</option><option>Editor</option></select></label><p class="note">${t('正式邀请需验证 Owner 身份、创建短期邀请并通过邮件服务发送。当前不发送邀请、不创建授权。','Invitations require verified Owner identity and email delivery. No invitation or permission will be created in this prototype.')}</p><div class="actions"><button type="button" data-close>${t('取消','Cancel')}</button><button class="primary">${t('检查服务状态','Check service status')}</button></div></form>`);$('#invite-form').onsubmit=e=>{e.preventDefault();toast(t('认证、协作与邮件服务待接入，未发送邀请。','Auth, collaboration and email services not connected. No invitation sent.'))}}}
